{"cards": [{"node_code": "N_614438d12cf649cc", "definition": "研究经消化道途径传播的感染性疾病，涵盖细菌、病毒及其他病原体引起的肠道感染，包括其临床表现、诊断、治疗及预防控制。", "boundary": "本节点聚焦于以消化道为主要传播途径或主要靶器官的传染病。包括霍乱、伤寒、细菌性痢疾、甲肝、戊肝、轮状病毒感染等。与“病毒性肝炎与肝衰竭”的区别在于，本节点侧重肠道症状及消化道传播，而肝炎节点侧重肝脏病理及血液/体液传播；与“医院感染”的区别在于，本节点侧重社区或自然疫源地的肠道传染病，院内腹泻若由特定肠道病原体引起可关联，但一般院内感染归入医院感染。", "includes": ["细菌性肠道感染（如霍乱、伤寒、副伤寒、细菌性痢疾）", "病毒性肠道感染（如甲型/戊型肝炎、轮状病毒、诺如病毒）", "其他肠道感染（如寄生虫性肠炎、阿米巴痢疾）"], "excludes": ["非感染性肠道疾病（如炎症性肠病、肠易激综合征）", "以血液或体液为主要传播途径的乙型/丙型肝炎（归入病毒性肝炎与肝衰竭）"], "sibling_distinctions": [{"other_code": "N_ff9890e3269feb79", "rule": "病毒性肝炎与肝衰竭侧重肝脏特异性损伤及血液/体液传播的肝炎病毒；肠道传染病侧重消化道症状及粪-口途径传播，虽甲戊肝属肠道传染病，但乙丙肝归入肝炎节点。"}, {"other_code": "N_2bb2924fddf2db1f", "rule": "医院感染与脓毒症侧重医疗机构内获得的感染；肠道传染病侧重自然传播或社区获得的消化道感染，除非特指院内暴发的肠道感染。"}], "cross_boundary_rule": "若疾病同时涉及肠道和肝脏（如甲肝），主挂载肠道传染病（因传播途径和初始靶器官），可关联病毒性肝炎节点。"}, {"node_code": "N_8ba4007215eb8a9c", "definition": "研究人类免疫缺陷病毒（HIV）感染及其导致的获得性免疫缺陷综合征（AIDS），涵盖病毒学基础、抗病毒治疗、机会性感染防治及免疫重建。", "boundary": "本节点专门针对HIV/AIDS及其直接后果。包括HIV基础科学、抗逆转录病毒治疗（ART）、AIDS相关机会性感染（如肺孢子菌肺炎、卡波西肉瘤）及免疫缺陷状态下的其他感染。与“医院感染”的区别在于，本节点侧重HIV特异性免疫缺陷导致的感染，而非一般院内获得性感染；与“呼吸道传染病”的区别在于，本节点侧重免疫缺陷背景下的感染，而非单纯呼吸道病原体传播。", "includes": ["HIV基础科学（病毒结构、复制、耐药性）", "抗病毒治疗（ART）方案及药物管理", "AIDS常见机会性感染（如PCP、CMV、结核、真菌感染）"], "excludes": ["非HIV引起的原发性免疫缺陷病（如先天性免疫缺陷，归入免疫学或遗传病）", "非免疫缺陷背景下的普通呼吸道感染（归入呼吸道传染病）"], "sibling_distinctions": [{"other_code": "N_005255d6a299ee7c", "rule": "呼吸道传染病侧重呼吸道病原体的传播与诊疗；本节点侧重HIV感染者因免疫缺陷而发生的呼吸道机会性感染（如PCP），主挂载本节点。"}, {"other_code": "N_2bb2924fddf2db1f", "rule": "医院感染侧重院内获得性感染；本节点侧重HIV/AIDS相关的机会性感染，无论发生场所，若由HIV免疫缺陷直接导致，主挂载本节点。"}], "cross_boundary_rule": "HIV感染者合并结核或真菌感染时，若强调免疫缺陷背景及HIV特异性管理，主挂载本节点；若仅讨论结核或真菌的通用诊疗，可关联相应传染病节点。"}, {"node_code": "N_2d191a0fc05375c4", "definition": "研究通过节肢动物媒介传播或人畜共患途径传播的传染病，涵盖虫媒病毒病、出血热、新发传染病及动物源性感染。", "boundary": "本节点聚焦于传播途径涉及节肢动物（蚊、蜱、蚤等）或动物宿主（人畜共患）的传染病。包括登革热、疟疾、莱姆病、狂犬病、埃博拉、马尔堡出血热等。与“呼吸道传染病”的区别在于传播媒介不同；与“肠道传染病”的区别在于非消化道传播；与“医院感染”的区别在于自然疫源性或动物源性。", "includes": ["虫媒病毒病（如登革热、寨卡、西尼罗河热、疟疾）", "其他人畜共患病（如狂犬病、布鲁氏菌病、炭疽）", "出血热与新发传染病（如埃博拉、马尔堡、拉沙热）"], "excludes": ["非虫媒或非人畜共患的呼吸道传染病（如流感、新冠，归入呼吸道传染病）", "非人畜共患的肠道传染病（如霍乱，归入肠道传染病）"], "sibling_distinctions": [{"other_code": "N_005255d6a299ee7c", "rule": "呼吸道传染病侧重空气/飞沫传播；本节点侧重虫媒或动物接触传播，即使部分虫媒病有呼吸道症状（如登革热），主挂载本节点。"}, {"other_code": "N_614438d12cf649cc", "rule": "肠道传染病侧重粪-口途径；本节点侧重虫媒或动物源性传播，即使部分人畜共患病有消化道症状（如布鲁氏菌病），主挂载本节点。"}], "cross_boundary_rule": "若疾病既可通过虫媒传播又可通过血液/体液传播（如疟疾），主挂载本节点（虫媒与人畜共患）；若为新发传染病且传播途径未明，暂归入本节点或待确认，但明确虫媒/动物源性的主挂载本节点。"}]}
